import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel for tril: zero out upper triangle elements
tril_kernel_source = """
__global__ void tril_kernel(const float* C_in, const float* out, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * N) {
        int i = idx / N;
        int j = idx % N;
        if (i >= j) {
            out[idx] = C_in[idx];
        } else {
            out[idx] = 0.0f;
        }
    }
}

torch::Tensor tril_cuda(const torch::Tensor c) {
    auto N = c.shape[0]; // assuming square matrix
    auto out = torch::zeros_like(c);
    const int block_size = 256;
    const int num_blocks = (N * N + block_size - 1) / block_size;
    tril_kernel<<<num_blocks, block_size>>>(c.data_ptr<float()>, out.data_ptr<float()>, N);
    return out;
}
"""

# Compile the custom CUDA function for tril
tril_custom = load_inline(
    name="custom_tril",
    cpp_sources=("torch::Tensor tril_cuda(const torch::Tensor c);"),
    cuda_sources=tril_kernel_source,
    functions=["tril_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.custom_tril = tril_custom

    def forward(self, A, B):
        # Standard matrix multiplication using PyTorch
        C_full = torch.matmul(A, B)
        out = self.custom_tril.tril_cuda(C_full)
        return out
